def requirements():
    extra_evidence = {
        'SHIP-04': [150], 'PL-06': [194, 235, 240],
        'REL-03': [194], 'TRACK-02': [382, 384],
        'REL-02': [539], 'NOT-01': [511],
    }
    rows = []
    for line in CATALOG.strip().splitlines():
        parts = line.split('|')
        if len(parts) != 6:
            raise ValueError('Invalid catalog row: ' + parts[0])
        key, group, title, numbers, behavior, acceptance = parts
        prompts = sorted(set([int(n) for n in numbers.split(',') if int(n) != 0]
                             + extra_evidence.get(key, [])))
        rows.append({'id': key, 'group': group, 'title': title, 'status': 'mandatory',
                     'source_kind': 'current_user_command' if '0' in numbers.split(',') else 'mcstar_user_prompt',
                     'prompts': prompts, 'requirement': behavior, 'acceptance': acceptance})
    return rows
